// Fake payment gateway. The first "failures" charge calls reject.
export function createFakeGateway({ failures = 0 } = {}) {
  const charges = [];
  let calls = 0;
  return {
    charges,
    async charge(amountCents) {
      await new Promise((r) => setTimeout(r, 1));
      if (++calls <= failures) throw new Error('gateway down');
      const charge = { id: 'ch_' + (charges.length + 1), amountCents };
      charges.push(charge);
      return charge;
    },
  };
}

