import { test, expect } from 'bun:test';
import { createFakeGateway } from '../src/gateway.js';
import { payOrder } from '../src/pay.js';
const ctx = () => ({ gateway: createFakeGateway(), payments: new Map() });
test('charges the amount and returns the charge id', async () => {
  const c = ctx();
  const r = await payOrder(c, { key: 'k1', orderId: 'o1', amountCents: 1500 });
  expect(r).toEqual({ chargeId: 'ch_1', amountCents: 1500 });
  expect(c.gateway.charges.length).toBe(1);
});
test('different keys charge separately', async () => {
  const c = ctx();
  await payOrder(c, { key: 'k1', orderId: 'o1', amountCents: 100 });
  await payOrder(c, { key: 'k2', orderId: 'o2', amountCents: 200 });
  expect(c.gateway.charges.length).toBe(2);
});

