import { test, expect } from 'bun:test';
import { createFakeGateway } from '../src/gateway.js';
import { payOrder } from '../src/pay.js';
const req = { key: 'k1', orderId: 'o1', amountCents: 1500 };
test('the same key later charges once and returns the same result', async () => {
  const c = { gateway: createFakeGateway(), payments: new Map() };
  const a = await payOrder(c, req);
  const b = await payOrder(c, req);
  expect(b).toEqual(a);
  expect(c.gateway.charges.length).toBe(1);
});
test('the same key while the first call is in flight charges once', async () => {
  const c = { gateway: createFakeGateway(), payments: new Map() };
  const [a, b, d] = await Promise.all([payOrder(c, req), payOrder(c, req), payOrder(c, req)]);
  expect(c.gateway.charges.length).toBe(1);
  expect(b).toEqual(a);
  expect(d).toEqual(a);
});
test('a failed charge is not remembered: the retry with the same key charges', async () => {
  const c = { gateway: createFakeGateway({ failures: 1 }), payments: new Map() };
  await expect(payOrder(c, req)).rejects.toThrow();
  const r = await payOrder(c, req);
  expect(r.amountCents).toBe(1500);
  expect(c.gateway.charges.length).toBe(1);
});
